```hcl
terraform {
  required_providers {
    aap = { source = "ansible/aap" }
  }
}
provider "aap" {
  host = "https://AAP_HOST"   # token via AAP_TOKEN env var
}
resource "aap_inventory" "inv" {
  name = "My new inventory"
  organization = 1
}
resource "aap_host" "h" {
  inventory_id = aap_inventory.inv.id
  name = "tf_host"
}
data "aap_job_template" "demo" {
  name = "Demo Job Template"
  organization_name = "Default"
}
resource "aap_job" "run" {
  inventory_id    = aap_inventory.inv.id
  job_template_id = data.aap_job_template.demo.id
  depends_on      = [aap_host.h]
}
```
The job template's inventory must be set to prompt on launch.
